package com.rpb.reservation.workforce;
import com.fasterxml.jackson.databind.ObjectMapper;import com.rpb.reservation.workforce.attendancepolicy.*;import static com.rpb.reservation.workforce.attendancepolicy.AttendancePolicyDtos.*;import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.workmode.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;
class WorkforceAttendancePolicyPostgresTest extends WorkforcePayrollPostgresTest {
 AttendancePolicyRepository policies;AttendancePolicyResolver policyResolver;AttendancePolicyService policyService;
 Arrangement arrangement=new Arrangement(List.of(1,2,3,4,5),LocalTime.of(9,0),480,60,180);
 @BeforeEach void setupPolicies(){var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());policies=new AttendancePolicyRepository(jdbc,json);policyResolver=new AttendancePolicyResolver(policies,repository,new WorkModeRepository(jdbc,json));policyService=proxy(new AttendancePolicyService(access,repository,policies,policyResolver,new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules()),time));}
 PolicyVersion defaults(String mode){return policyService.saveDefault(admin,store,UUID.randomUUID(),new DefaultWrite(0L,LocalDate.of(2026,10,29),mode,arrangement));}
 @Test void defaultNeverAutomaticallyAdoptsAndSnapshotsStayFixed(){var d=defaults("default_normal");assertThat(policyResolver.resolve(tenant,company,employee,LocalDate.of(2026,11,2)).mode()).isEqualTo("clock");var id=UUID.randomUUID();var c=new AssignmentWrite(0L,LocalDate.of(2026,10,29),true,d.id(),null,null);var a=policyService.save(admin,store,employee,id,c);assertThat(policyService.save(admin,store,employee,id,c)).isEqualTo(a);policyService.saveDefault(admin,store,UUID.randomUUID(),new DefaultWrite(1L,LocalDate.of(2026,10,30),"contract",null));jdbc.update("update workforce_employees set main_store_id=? where id=?",sibling,employee);var resolved=policyResolver.resolve(tenant,company,employee,LocalDate.of(2026,11,2));assertThat(resolved.mode()).isEqualTo("default_normal");assertThat(resolved.sourceStoreId()).isEqualTo(store);assertThat(policyResolver.resolve(tenant,company,employee,LocalDate.of(2026,10,28)).mode()).isEqualTo("clock");assertThat(policyResolver.expected(tenant,company,employee,LocalDate.of(2026,11,2),LocalDate.of(2026,11,2))).singleElement().satisfies(e->{assertThat(e.standardWorkSeconds()).isEqualTo(28800);assertThat(e.breakStart()).isEqualTo(e.start().plusSeconds(10800));assertThat(e.breakEnd()).isEqualTo(e.breakStart().plusSeconds(3600));});assertThatThrownBy(()->policyService.save(admin,store,employee,id,new AssignmentWrite(0L,LocalDate.of(2026,10,29),false,null,"free",null))).extracting("code").isEqualTo("WORKFORCE_CONFLICT");}
 @Test void freeFallbackAndNoArtificialContractHours(){jdbc.update("insert into workforce_work_modes(id,tenant_id,employee_id,effective_from,mode,origin,position_version,version) values(?,?,?,?,'free','personal',0,1)",UUID.randomUUID(),tenant,employee,LocalDate.of(2026,10,1));defaults("default_normal");assertThat(policyResolver.resolve(tenant,company,employee,LocalDate.of(2026,11,2)).mode()).isEqualTo("free");policyService.save(admin,store,employee,UUID.randomUUID(),new AssignmentWrite(0L,LocalDate.of(2026,10,29),false,null,"contract",arrangement));assertThat(policyResolver.expected(tenant,company,employee,LocalDate.of(2026,11,1),LocalDate.of(2026,11,30))).isEmpty();}
 @Test void plainEmployeeAndPartialManagerCannotWriteAndSelfCanRead(){jdbc.update("insert into workforce_administrators(tenant_id,store_id,account_id,employee_manage,payroll_company_id,version) values(?,?,?,false,?,1)",tenant,store,employeeAccount,company);assertThat(policyService.self(worker,store).employeeId()).isEqualTo(employee);assertThatThrownBy(()->policyService.save(worker,store,employee,UUID.randomUUID(),new AssignmentWrite(0L,LocalDate.of(2026,10,29),false,null,"free",null))).extracting("code").isEqualTo("WORKFORCE_FORBIDDEN");var limited=new com.rpb.reservation.walkin.api.CurrentActor(tenant,adminId,"staff",Set.of("tenant_admin"),Set.of("workforce.view","workforce.admin.manage","tenant.admin.manage"),Set.of(store));assertThatThrownBy(()->policyService.page(limited,store,employee)).extracting("code").isEqualTo("WORKFORCE_FORBIDDEN");assertThatThrownBy(()->policyResolver.resolve(UUID.randomUUID(),company,employee,LocalDate.of(2026,11,2))).extracting("code").isEqualTo("WORKFORCE_NOT_FOUND");}

 @Test void concurrentAssignmentsAndAppendOnlyDatesAreSafe()throws Exception{var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var start=new java.util.concurrent.CountDownLatch(1);try{var calls=new ArrayList<java.util.concurrent.Future<Boolean>>();for(var mode:List.of("free","contract"))calls.add(pool.submit(()->{start.await();try{policyService.save(admin,store,employee,UUID.randomUUID(),new AssignmentWrite(0L,LocalDate.of(2026,10,29),false,null,mode,null));return true;}catch(com.rpb.reservation.workforce.domain.WorkforceException ex){assertThat(ex.code()).isEqualTo("WORKFORCE_CONFLICT");return false;}}));start.countDown();int wins=0;for(var call:calls)if(call.get(20,java.util.concurrent.TimeUnit.SECONDS))wins++;assertThat(wins).isEqualTo(1);assertThat(policies.assignments(tenant,employee)).hasSize(1);assertThatThrownBy(()->policyService.save(admin,store,employee,UUID.randomUUID(),new AssignmentWrite(1L,LocalDate.of(2026,10,29),false,null,"free",null))).extracting("code").isEqualTo("WORKFORCE_INVALID");}finally{pool.shutdownNow();}}
 @Test void gateAndScopeForeignKeysAreEnforced(){for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){org.mockito.Mockito.doAnswer(c->{com.rpb.reservation.appgate.application.AppGateAccessRequest r=c.getArgument(0);return com.rpb.reservation.appgate.domain.AppGateDecision.deny(r.appKey(),r.tenantId(),r.storeId(),r.requiredPermission(),reason);}).when(gate).evaluate(org.mockito.ArgumentMatchers.any());assertThatThrownBy(()->policyService.page(admin,store,employee)).extracting("code").isEqualTo(reason.name());assertThatThrownBy(()->policyService.saveDefault(admin,store,UUID.randomUUID(),new DefaultWrite(0L,LocalDate.of(2026,10,29),"free",null))).extracting("code").isEqualTo(reason.name());}assertThatThrownBy(()->policies.insert(tenant,adminId,new PolicyVersion(UUID.randomUUID(),employee,otherCompany,store,LocalDate.of(2026,10,29),"free","personal",null,0,null,"Asia/Singapore",1))).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}
}
